async function initStorage(){if(DATABASE_URL){pool=new Pool({connectionString:DATABASE_URL,ssl:DATABASE_URL.includes('localhost')?false:{rejectUnauthorized:false}});await pool.query('CREATE TABLE IF NOT EXISTS game_state(id INT PRIMARY KEY,data JSONB NOT NULL,updated_at TIMESTAMPTZ DEFAULT NOW())');const r=await pool.query('SELECT data FROM game_state WHERE id=1');if(r.rows[0])db=r.rows[0].data;else await pool.query('INSERT INTO game_state(id,data) VALUES(1,$1)',[db]);console.log('PostgreSQL persistence ON')}else{if(fs.existsSync(DB_FILE)){try{db=JSON.parse(fs.readFileSync(DB_FILE,'utf8'))}catch(e){console.error('db.json read failed:',e.message)}}if(DATA_DIR==='/var/data'||process.env.DATA_DIR)console.log('Persistent file storage path:',DB_FILE);else console.warn('WARNING: DATABASE_URL/DATA_DIR missing. Render deploy may erase ./data/db.json and reset players. Configure PostgreSQL or a persistent disk.')}normalize();await saveNow()}
async function saveNow(){if(pool)await pool.query('INSERT INTO game_state(id,data,updated_at) VALUES(1,$1,NOW()) ON CONFLICT(id) DO UPDATE SET data=$1,updated_at=NOW()',[db]);else fs.writeFileSync(DB_FILE,JSON.stringify(db,null,2))}
function saveSoon(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveNow().catch(console.error),100)}

