function newUser(name,pw,role='player',email=''){const h=hpw(pw);return{id:crypto.randomUUID(),name,email:String(email||'').trim().toLowerCase().slice(0,120),...h,role,banned:false,vip:false,vipUntil:0,cash:2500000,bank:0,turns:300,hp:100,level:1,xp:0,rep:0,wanted:0,jailedUntil:0,insurance:{active:false,until:0,coverage:.3},privacy:{cash:true,bank:false,levels:true,stats:true,lastActive:false},education:0,educationProgress:0,securityLevel:1,mafiaLevel:1,propertyLevel:0,mafia:0,guards:0,weapons:{},crypto:0,city:'Paide',businesses:{},carLicense:0,cars:[],gangId:null,spies:{finnish:0,ukrainian:0,russian:0},intelLevel:0,lastSpyAt:{},bodyguard:null,bodyguardUntil:0,guardingClient:null,guardingUntil:0,businessProjects:{},businessWorkers:{},businessRejected:{},lastTurnAt:Date.now(),lastActive:Date.now(),createdAt:Date.now(),jobId:null,lastSalaryAt:Date.now(),pvpHits:{},maintenanceDue:Date.now()+86400000,sessionVersion:1,lastIp:'',lastUserAgent:'',lastLoginAt:0,failedLogins:0,lockedUntil:0,stats:{wins:0,losses:0,robbed:0,pokerWins:0,crimes:0,operations:0}}}
function bankLimit(u){return EDU[u.education]?.bank||1e6}
function chargeMaintenance(u){const property=PROPERTY_PRICES[u.propertyLevel]||0,troops=(u.mafia+u.guards)*250,weaponValue=Object.entries(u.weapons||{}).reduce((s,[i,q])=>s+weaponPrice(i)*q,0),biz=Object.entries(u.businesses||{}).reduce((s,[id,l])=>s+(BIZ.find(x=>x.id===id)?.base||0)*l*.01,0),fee=Math.floor(property*db.settings.maintenanceRate+troops+weaponValue*.0005+biz);u.cash=Math.max(0,u.cash-fee);return fee}
function refresh(u){const now=Date.now(),step=Math.max(60000,Number(db.settings.turnMinutes||15)*60000);if(!Number.isFinite(Number(u.lastTurnAt))||u.lastTurnAt<=0||u.lastTurnAt>now)u.lastTurnAt=now;const n=Math.floor((now-u.lastTurnAt)/step);if(n>0){if(u.turns<db.settings.maxNaturalTurns)u.turns=Math.min(db.settings.maxNaturalTurns,u.turns+n*db.settings.turnBatch);u.lastTurnAt+=n*step}const j=jobFor(u);if(!Number.isFinite(Number(u.lastSalaryAt))||u.lastSalaryAt<=0||u.lastSalaryAt>now)u.lastSalaryAt=now;if(j){const pays=Math.floor((now-u.lastSalaryAt)/SALARY_INTERVAL);if(pays>0){u.cash+=pays*j.pay;u.lastSalaryAt+=pays*SALARY_INTERVAL}}else u.lastSalaryAt=now;if(now>=u.maintenanceDue){chargeMaintenance(u);u.maintenanceDue=now+86400000}}
