app.post('/api/bank',auth,(req,res)=>{const u=req.user,a=Math.floor(+req.body.amount||0);if(a<=0)return res.status(400).json({error:'Vigane summa.'});if(req.body.dir==='in'){if(a>u.cash)return res.status(400).json({error:'Sularaha puudub.'});if(u.bank+a>bankLimit(u))return res.status(400).json({error:`Pangalimiit ${bankLimit(u)} €.`});u.cash-=a;u.bank+=a}else{if(a>u.bank)return res.status(400).json({error:'Pangas pole piisavalt.'});u.bank-=a;u.cash+=a}ok(res,u)});
app.post('/api/levelup',auth,(req,res)=>{const u=req.user,t=req.body.type,field=t==='mafia'?'mafiaLevel':t==='security'?'securityLevel':t==='property'?'propertyLevel':null;if(!field)return res.status(400).json({error:'Vigane level.'});const max=t==='property'?100:300,n=u[field]+1,cost=Math.floor((t==='property'?PROPERTY_PRICES[n]:LEVEL_PRICES[n])*market());if(n>max)return res.status(400).json({error:'Max level.'});if(u.cash<cost)return res.status(400).json({error:`Vaja ${cost} €.`});u.cash-=cost;u[field]=n;ok(res,u,{message:`${t} level ${n}`})});
app.post('/api/troops',auth,(req,res)=>{const u=req.user,type=req.body.type,n=Math.max(1,Math.min(100000,Math.floor(+req.body.n||0))),unit=type==='mafia'?12000:13500;if(!['mafia','guards'].includes(type))return res.status(400).json({error:'Vigane tüüp.'});const cost=Math.floor(n*unit*market()),turns=n*5;if(u.cash<cost)return res.status(400).json({error:`Vaja ${cost} €.`});if(!needTurns(u,turns))return res.status(400).json({error:`Vaja ${turns} käiku.`});u.cash-=cost;gameIncome(cost,'troop_purchase',u);u[type]+=n;ok(res,u,{message:`+${n} ${type} · ${turns} käiku`})});
app.post('/api/weapon',auth,(req,res)=>{const u=req.user,i=Math.floor(+req.body.index),q=Math.max(1,Math.min(10000,Math.floor(+req.body.q||1))),w=WEAPONS[i];if(!w)return res.status(400).json({error:'Vigane relv.'});const cost=Math.floor(weaponPrice(i)*market(db.settings.weaponMarket)*q),turns=5*q;db.settings.marketPressure+=q;if(u.cash<cost)return res.status(400).json({error:'Raha pole piisavalt.'});if(!needTurns(u,turns))return res.status(400).json({error:`Vaja ${turns} käiku.`});u.cash-=cost;gameIncome(cost,'weapon_purchase',u);u.weapons[i]=(u.weapons[i]||0)+q;ok(res,u,{message:`Ostsid ${q} × ${w.name}`})});
app.post('/api/crime',auth,(req,res)=>{const u=req.user,c=CRIMES.find(x=>x.id===req.body.id);if(!freeToAct(u))return res.status(403).json({error:'Oled vanglas.'});if(!c||u.level<c.need)return res.status(400).json({error:'Rööv lukus.'});if(!needTurns(u,c.turns))return res.status(400).json({error:`Vaja ${c.turns} käiku.`});const cb=combat(u),fail=clamp(c.risk-cb.atk/(cb.atk+3e6),.04,.72);let msg;if(Math.random()<fail){let loss=Math.floor(rand(c.min,c.max)*.25);if(u.insurance?.active&&u.insurance.until>Date.now()){const refund=insuranceCover(u,loss);loss-=refund;msg=`Kindlustus kattis ${refund} €. `}else msg='';u.cash=Math.max(0,u.cash-loss);u.wanted=clamp((u.wanted||0)+2,0,100);if(Math.random()<clamp(.08+u.wanted/180,.08,.65)){const mins=5+Math.floor(u.wanted/5);u.jailedUntil=Date.now()+mins*60000;msg+=`Jäid ${mins} minutiks vangi. `}msg+=`Rööv ebaõnnestus. Kaotasid ${loss} €.`}else{const g=Math.floor(rand(c.min,c.max)*db.settings.heistMultiplier);u.cash+=g;u.stats.crimes++;u.wanted=clamp((u.wanted||0)+1+Math.floor(c.risk*5),0,100);u.rep=clamp((u.rep||0)+1,-1000,1000);u.level=Math.max(u.level||1,1+Math.floor(Math.sqrt(u.stats.crimes/5)));u.xp=Math.max(Number(u.xp||0),u.stats.crimes*10);msg=`Rööv õnnestus: +${g} €.`}ok(res,u,{message:msg})});
