app.post('/api/rob-player',auth,(req,res)=>{const a=req.user,b=resolveUser(req.body.targetName||req.body.targetId);if(!b||b.id===a.id)return res.status(400).json({error:'Vigane sihtmärk.'});if(['owner','admin'].includes(b.role))return res.status(403).json({error:'Mängu omanikku/admini ei saa rünnata.'});if(!freeToAct(a))return res.status(403).json({error:'Oled vanglas.'});const now=Date.now(),winMs=db.settings.pvpWindowMin*60000,k=b.id,h=(a.pvpHits[k]||[]).filter(t=>now-t<winMs);if(h.length>=db.settings.pvpMaxHits)return res.status(429).json({error:`Seda mängijat saad ${db.settings.pvpWindowMin} min jooksul rünnata max ${db.settings.pvpMaxHits} korda.`});if(!needTurns(a,30))return res.status(400).json({error:'Vaja 30 käiku.'});h.push(now);a.pvpHits[k]=h;const A=combat(a),B=combat(b);let msg;if(A.atk>B.def){const take=Math.max(0,Math.floor(b.cash*.50));b.cash-=take;a.cash+=take;let covered=insuranceCover(b,take);if(covered>0){b.cash+=covered;db.gameBank.balance=Math.max(0,(db.gameBank.balance||0)-covered);db.gameBank.log.unshift({time:Date.now(),type:'insurance_payout',amount:-covered,userId:b.id,user:b.name})}a.stats.wins++;b.stats.losses++;msg=`Võit! Röövisid ${take} € (50% ohvri hetkesularahast).`;notify(b,'pvp',`${a.name} ründas sind. Kaotasid ${take} €. Kindlustus kattis ${covered} €.`,{attacker:a.id,lost:take,covered});if(a.gangId&&db.gangs[a.gangId]){const g=db.gangs[a.gangId];g.points=(g.points||0)+1;recordGangAttack(g,a,true)}for(const bo of Object.values(db.bounties)){if(bo.active&&bo.targetId===b.id){bo.progress=bo.progress||{};bo.progress[a.id]=(bo.progress[a.id]||0)+1;if(bo.progress[a.id]>=(bo.requiredHits||1)){a.cash+=bo.reward;bo.active=false;bo.claimedBy=a.id;bo.claimedAt=Date.now();msg+=` Pearaha +${bo.reward} €.`}}}const loose=freeWeaponMap(b);let stolenTotal=0,stolenNames=[];for(const[i,q]of Object.entries(loose)){const stolen=Math.min(q,Math.max(1,Math.floor(q*.20)));if(stolen>0){b.weapons[i]-=stolen;a.weapons[i]=(a.weapons[i]||0)+stolen;stolenTotal+=stolen;stolenNames.push(`${WEAPONS[i]?.name||'relv'} ×${stolen}`)}}if(stolenTotal){msg+=` Vabu relvi saagiks: ${stolenNames.join(', ')}.`;notify(b,'pvp',`Kaotasid kaitsmata relvi: ${stolenNames.join(', ')}.`)}}else{a.stats.losses++;b.stats.wins++;if(a.gangId&&db.gangs[a.gangId]){const g=db.gangs[a.gangId];recordGangAttack(g,a,false)}msg=`Rünnak ebaõnnestus. Sinu Attack ${Math.floor(A.atk)} ≤ vastase Defense ${Math.floor(B.def)}.`;notify(b,'pvp',`${a.name} proovis sind rünnata, kuid sinu kaitse pidas.`,{attacker:a.id})}ok(res,a,{message:msg})});
