function settleLoans(){
  const now=Date.now();
  for(const l of Object.values(db.loans)){
    if(l.status!=='active'||now<l.due)continue;
    const u=byId(l.borrower),b=db.playerBanks[l.bankOwner];
    if(!u||!b)continue;
    const due=Math.floor(l.principal*(1+l.rate/100));
    let debt=due,paid=0;
    const take=(field)=>{const x=Math.min(debt,Math.max(0,Math.floor(u[field]||0)));u[field]-=x;debt-=x;paid+=x};
    take('cash');take('bank');
    if(debt>0&&u.crypto>0){const unit=Math.max(1,Math.floor(db.settings.cryptoPrice||1)),q=Math.min(u.crypto,Math.ceil(debt/unit)),v=Math.min(debt,q*unit);u.crypto-=q;debt-=v;paid+=v}
    while(debt>0&&(u.cars||[]).length){const c=u.cars.pop(),v=Math.max(1,Math.floor((c.market||c.buy||0)*market(db.settings.carMarket)*.7));debt-=v;paid+=v}
    if(debt>0){
      for(const [i,q0] of Object.entries(u.weapons||{})){
        let q=q0;
        while(debt>0&&q>0){const v=Math.max(1,Math.floor(weaponPrice(i)*market(db.settings.weaponMarket)*.5));q--;debt-=v;paid+=v}
        u.weapons[i]=q;if(debt<=0)break;
      }
    }
    if(debt>0){
      for(const [id,lvl] of Object.entries(u.businesses||{})){
        if(lvl<=0)continue;const bz=BIZ.find(x=>x.id===id);if(!bz)continue;
        const v=Math.max(1,Math.floor(bz.base*Math.pow(2.05,Math.max(0,lvl-1))*market()*.6));
        delete u.businesses[id];delete u.businessProjects[id];delete u.businessWorkers[id];debt-=v;paid+=v;if(debt<=0)break;
      }
    }
    b.capital+=Math.min(due,paid);u.rep=Math.max(-1000,(u.rep||0)-50);l.status=debt<=0?'liquidated':'defaulted';l.unpaid=Math.max(0,debt);
    notify(u,'loan',debt<=0?'Laen aegus ja võlg kaeti automaatselt sinu rahast/varast.':`Laen aegus. Vara likvideeriti, kuid ${Math.floor(debt)} € jäi tasumata.`);
  }
  saveSoon();
}
