app.post('/api/spy',auth,(req,res)=>{const u=req.user,t=resolveUser(req.body.targetName||req.body.targetId),type=String(req.body.type||'finnish');if(!t||t.id===u.id)return res.status(400).json({error:'Vigane siht.'});if(['owner','admin'].includes(t.role))return res.status(403).json({error:'Ownerit/admini ei saa spioneerida.'});if(!freeToAct(u))return res.status(403).json({error:'Oled vanglas.'});const last=u.lastSpyAt[t.id]||0;if(Date.now()-last<15*60000)return res.status(429).json({error:'Sama mängijat saab spioneerida 1× 15 minuti jooksul.'});if(!(u.spies[type]>0))return res.status(400).json({error:'Seda tüüpi spiooni pole.'});const spyTurns={finnish:5,ukrainian:10,russian:15}[type]||5;if(!needTurns(u,spyTurns))return res.status(400).json({error:`Vaja ${spyTurns} käiku.`});u.spies[type]=Math.max(0,Number(u.spies[type]||0)-1);u.lastSpyAt[t.id]=Date.now();const skill=SPY_TYPES[type]?.skill||.55,def=Math.min(.55,(t.guards||0)/100000+(t.securityLevel||1)/1200),success=Math.random()<clamp(skill-def,.12,.9);if(!success){if(Math.random()<.6)notify(t,'spy',`${u.name} proovis sind spioneerida, kuid jäi vahele.`);return ok(res,u,{message:'Spionaaž ebaõnnestus.'})}const intel={cash:t.cash,bankRange:t.bank<1e6?'alla 1M':t.bank<100e6?'1M–100M':t.bank<1e9?'100M–1B':'üle 1B',mafia:t.mafia,guards:t.guards,weapons:Object.values(t.weapons||{}).reduce((a,b)=>a+b,0),combat:combat(t),businesses:Object.keys(t.businesses||{}).length};ok(res,u,{message:'Spionaaž õnnestus.',intel})});
app.post('/api/jail/bail-other',auth,(req,res)=>{const u=req.user,t=resolveUser(req.body.targetName||req.body.targetId);if(!t||!t.jailedUntil||t.jailedUntil<=Date.now())return res.status(400).json({error:'Mängija pole vanglas.'});const mins=Math.ceil((t.jailedUntil-Date.now())/60000),cost=Math.floor(Math.max(50000,mins*50000*(1+t.wanted/100))*market());if(u.cash<cost)return res.status(400).json({error:`Kautsjon maksab ${cost} €.`});u.cash-=cost;gameIncome(cost,'bail',u);t.jailedUntil=0;t.wanted=Math.max(0,t.wanted-10);notify(t,'jail',`${u.name} maksis sinu kautsjoni ${cost} € ja vabastas sind.`);ok(res,u,{message:`Maksid ${t.name} kautsjoni ${cost} €.`})});
app.post('/api/business/workers',auth,(req,res)=>{const u=req.user,b=BIZ.find(x=>x.id===req.body.id),n=clamp(Math.floor(+req.body.n||1),1,1000);if(!b||(u.businesses[b.id]||0)<1)return res.status(400).json({error:'Firma puudub.'});const unit=Math.floor((db.settings.workerBasePrice||25000)*market()),cost=unit*n,turns=Math.max(5,n);if(u.cash<cost)return res.status(400).json({error:`Töötajad maksavad ${cost} €.`});if(!needTurns(u,turns))return res.status(400).json({error:`Vaja ${turns} käiku.`});u.cash-=cost;gameIncome(Math.floor(cost*(db.settings.businessTax||.08)),'worker_fee',u);u.businessWorkers[b.id]=(u.businessWorkers[b.id]||0)+n;ok(res,u,{message:`${b.name}: +${n} töötajat.`})});
app.post('/api/business/project',auth,(req,res)=>{const u=req.user,b=BIZ.find(x=>x.id===req.body.id),lvl=b?(u.businesses[b.id]||0):0;if(!b||lvl<1)return res.status(400).json({error:'Firma puudub.'});if(!freeToAct(u))return res.status(403).json({error:'Oled vanglas.'});if((u.wanted||0)>=90)return res.status(403).json({error:'Wanted on liiga kõrge uue projekti alustamiseks.'});const cur=u.businessProjects[b.id];if(cur&&cur.endsAt>Date.now())return res.status(400).json({error:'Selle firma projekt juba käib.'});const list=(BUSINESS_PROJECTS[b.id]||[]).map(p=>projectCfg(b.id,p)),z=list.find(x=>x.id===String(req.body.projectId||''))||list[0];if(!z)return res.status(400).json({error:'Projekt puudub.'});const workers=u.businessWorkers[b.id]||0,assigned=clamp(Math.floor(+req.body.workers||z.workers),z.workers,workers||z.workers);if(workers<z.workers)return res.status(400).json({error:`Vaja vähemalt ${z.workers} töötajat.`});const cost=Math.floor(b.base*Math.max(1,lvl)*z.costMult*market());if(u.cash<cost)return res.status(400).json({error:`Projektikulu ${cost} €.`});if(!needTurns(u,z.turns))return res.status(400).json({error:`Vaja ${z.turns} käiku.`});u.cash-=cost;gameIncome(Math.floor(cost*(db.settings.businessTax||.08)),'business_fee',u);u.businessProjects[b.id]={id:crypto.randomUUID(),projectId:z.id,name:z.name,startedAt:Date.now(),endsAt:Date.now()+z.hours*3600000,cost,reward:Math.floor(cost*z.rewardMult*(1+.04*Math.max(0,lvl-1))*(1+Math.min(.30,Math.max(0,assigned-z.workers)*.02))),workers:assigned};delete u.businessRejected[b.id+'|'+z.id];ok(res,u,{message:`${b.name}: ${z.name} käivitatud ${z.hours} tunniks. Algkulu ${cost} €, töötajaid ${assigned}.`})});
app.post('/api/business/project-reject',auth,(req,res)=>{const u=req.user,b=BIZ.find(x=>x.id===req.body.id),pid=String(req.body.projectId||'');if(!b||!pid)return res.status(400).json({error:'Vigane projekt.'});u.businessRejected=u.businessRejected||{};u.businessRejected[b.id+'|'+pid]=Date.now()+30*60000;ok(res,u,{message:'Projektist keeldutud. Pakkumine kaob 30 minutiks.'})});
app.post('/api/business/project-collect',auth,(req,res)=>{const u=req.user,b=BIZ.find(x=>x.id===req.body.id),p=b&&u.businessProjects[b.id];if(!p)return res.status(400).json({error:'Aktiivset projekti pole.'});if(Date.now()<p.endsAt)return res.status(400).json({error:'Projekt pole veel valmis.'});const taxRate=clamp(Number(db.settings.businessTax||.08),0,.9),gross=Math.floor(p.reward*market()),tax=Math.floor(gross*taxRate),net=gross-tax;u.cash+=net;gameIncome(tax,'business_tax',u);delete u.businessProjects[b.id];ok(res,u,{message:`Projekt valmis: bruto ${gross} €, maks ${tax} €, kätte ${net} €.`})});
